-- oracle: pub400
SELECT ROUTINE_SCHEMA, ROUTINE_NAME, ROUTINE_TYPE, EXTERNAL_NAME FROM QSYS2.SYSROUTINES WHERE ROUTINE_SCHEMA IN ('QSYS2','QSYS','SYSTOOLS') AND (ROUTINE_NAME LIKE '%PLAN_CACHE%' OR ROUTINE_NAME LIKE '%EXPLAIN%' OR ROUTINE_NAME LIKE 'QQQ%' OR ROUTINE_NAME LIKE '%STATISTIC%' OR ROUTINE_NAME LIKE '%QAQQINI%') ORDER BY 1, 2;
SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE FROM QSYS2.SYSTABLES WHERE TABLE_SCHEMA IN ('QSYS2','QSYS','SYSTOOLS','SYSIBM') AND (TABLE_NAME LIKE '%PLAN%' OR TABLE_NAME LIKE '%STAT%' OR TABLE_NAME LIKE '%EXPLAIN%') ORDER BY 1, 2;
SELECT SPECIFIC_SCHEMA, SPECIFIC_NAME, ORDINAL_POSITION, PARAMETER_MODE, PARAMETER_NAME, DATA_TYPE, CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION, DEFAULT FROM QSYS2.SYSPARMS WHERE SPECIFIC_SCHEMA = 'QSYS2' AND (SPECIFIC_NAME LIKE '%PLAN_CACHE%' OR SPECIFIC_NAME LIKE '%EXPLAIN%') ORDER BY 1, 2, 3;
SELECT COLUMN_NAME, ORDINAL_POSITION, DATA_TYPE, LENGTH, NUMERIC_SCALE, IS_NULLABLE FROM QSYS2.SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSYS2' AND TABLE_NAME = 'SYSCOLUMNSTAT' ORDER BY 2;
